function pmt(rate, n, principal){ if(!(principal>0)) return 0; if(rate<=0) return principal/n;
  var m=rate/12; return principal*m/(1-Math.pow(1+m,-n)); }
function rentVsBuy(o){
  o=o||{}; var P=o.price==null?1000000:+o.price, down=o.downPct==null?20:+o.downPct, r=o.rate==null?0.05:+o.rate, Y=o.years==null?30:+o.years;
  var R0=o.rent==null?3000:+o.rent, i=o.rentInfl==null?0.03:+o.rentInfl, g=o.investReturn==null?0.06:+o.investReturn, h=o.homeAppr==null?0.03:+o.homeAppr;
  if(!(P>0)||!(Y>0)) return {error:'房价与年限须为正'};
  var principal=P*(1-down/100); var M=pmt(r,Y*12,principal);
  var months=Y*12; var bal=principal; var buyNW, rentPort=0; var curRent=R0;
  for(var mo=1;mo<=months;mo++){
    if(mo>1) curRent*=(1+i/12);
    var interest=bal*(r/12); var principalPaid=M-interest; bal-=principalPaid; if(bal<0) bal=0;
    var surplus=(principal/Y/12)+M-curRent; rentPort=rentPort*(1+g/12)+surplus;
  }
  var homeValue=P*Math.pow(1+h,Y); buyNW=homeValue-bal;
  return {mortgage:Math.round(M), buyNW:Math.round(buyNW), rentNW:Math.round(rentPort),
          better: buyNW>=rentPort?'买房':'租房', homeValue:Math.round(homeValue)}; }
var EXPORTS={rentVsBuy:rentVsBuy, pmt:pmt};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.RentVsBuyForgePure = EXPORTS; }
